const r = phi.goto("https://www.carvana.com/cars/honda-civic");
phi.sleep(3000);
const obs = phi.observe({ maxElements: 120 });
return { url: r.url, title: r.title, total: obs.total, text: obs.text.slice(0, 2500), nodes: obs.nodes.slice(0,50) };

phi.narrate("等待网站安全验证通过");
phi.sleep(8000);
const obs = phi.observe({ maxElements: 40 });
return { url: obs.url, title: obs.title, total: obs.total, text: obs.text.slice(0, 1200) };

phi.narrate("安全验证还卡着，重新加载页面试试");
phi.sleep(5000);
const o1 = phi.observe({ maxElements: 20 });
let title1 = o1.title, total1 = o1.total;
if (o1.total <= 6) {
  phi.goto("https://www.carvana.com/cars/honda-civic");
  phi.sleep(6000);
  const o2 = phi.observe({ maxElements: 20 });
  return { first: { title: title1, total: total1, text: o1.text.slice(0,300) }, second: { url: o2.url, title: o2.title, total: o2.total, text: o2.text.slice(0,800) } };
}
return { first: { url: o1.url, title: title1, total: total1, text: o1.text.slice(0,1500) }, nodes: o1.nodes.slice(0,30) };

const obs = phi.observe({ maxElements: 300 });
const nodes = obs.nodes.map(n => ({ ref: n.ref, role: n.role, name: (n.name||"").slice(0,80), owner: n.owner, off: n.offscreen }));
phi.keep("step6_nodes", nodes);
return { url: obs.url, title: obs.title, total: obs.total, text: obs.text.slice(0, 1200), nodes: nodes.slice(0, 120) };

const obs = phi.observe({ maxElements: 60 });
const brief = obs.nodes.map(n => `${n.ref}|${n.role}|${(n.name||"").slice(0,50)}|${n.owner||""}${n.offscreen?"|off":""}`);
const cards = phi.query("a[href*='/vehicle/']", { fields: ["href"], limit: 20 });
return { url: obs.url, total: obs.total, nodes: brief, cardCount: cards.total, cards: cards.items.slice(0,10) };

phi.narrate("页面出来了，开始套筛选条件：先点「2.5万美元以下」");
const a = phi.click(38);
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 8000 });
const o = phi.observe({ maxElements: 50 });
const brief = o.nodes.map(n => `${n.ref}|${n.role}|${(n.name||"").slice(0,40)}`);
return { click: a, url: o.url, brief: brief.slice(0,50), text: o.text.slice(0,600) };

const o = phi.observe({ maxElements: 200 });
const brief = o.nodes.map(n => `${n.ref}|${n.role}|${(n.name||"").slice(0,45)}`);
const quick = o.nodes.filter(n => /Under|Apple|Adaptive|Blindspot|Sort|Features|Year/i.test(n.name||"")).map(n => `${n.ref}|${n.name.slice(0,60)}`);
return { url: o.url, total: o.total, quick, briefHead: brief.slice(0,45) };

const targets = ["Under 30,000 miles", "Apple CarPlay", "Adaptive Cruise Control", "Blindspot Sensors"];
const log = [];
for (const t of targets) {
  const o = phi.observe({ maxElements: 120 });
  const btn = o.nodes.filter(n => n.role === "button" && (n.name||"").startsWith(t)).pop();
  if (!btn) { log.push(t + " -> NOT FOUND"); continue; }
  phi.narrate("正在勾选：" + t);
  const r = phi.click(btn.ref);
  phi.waitForNetworkIdle({ idleMs: 700, timeoutMs: 8000 });
  log.push(t + " -> clicked ref " + btn.ref + " url=" + r.url);
}
const o2 = phi.observe({ maxElements: 200 });
return {
  log,
  url: o2.url,
  removes: o2.nodes.filter(n => /^Remove/.test(n.name||"")).map(n => n.ref + "|" + n.name),
  count: o2.nodes.filter(n => /^View /.test(n.name||"")).length,
  sort: o2.nodes.filter(n => /Sort by/.test(n.name||"")).map(n => n.ref + "|" + n.name)
};

const o = phi.observe({ maxElements: 250 });
const low = o.nodes.filter(n => /Lowest price/i.test(n.name||"")).map(n=>`${n.ref}|${n.role}|${n.name}`);
const viewBtns = o.nodes.filter(n => /^View /.test(n.name||"")).length;
return { low, viewBtns, total: o.total };

const q = phi.query("select", { limit: 20 });
const o = phi.observe({ maxElements: 300 });
const combo = o.nodes.filter(n => /combobox|listbox|select/i.test(n.role||"") || /sort/i.test((n.name||"") + " " + (n.attrs?.name||""))).map(n => `${n.ref}|${n.role}|${(n.name||"").slice(0,60)}`);
return { selects: q.total, selItems: q.items.slice(0,5), combo: combo.slice(0,20) };

const o = phi.observe({ maxElements: 400 });
const heads = o.text ? o.text.slice(0, 3000) : "";
const cards = phi.query("[data-testid='vehicle-card'], .vehicle-card, article", { limit: 30 });
const viewBtns = o.nodes.filter(n => /^View /.test(n.name||"")).map(n => `${n.ref}|${n.name.slice(0,40)}`);
return { textHead: heads.slice(0,1500), cardsTotal: cards.total, cardsItems: cards.items.slice(0,6), viewBtns, elemCount: o.total };

const o = phi.observe({ maxElements: 500 });
const menuish = o.nodes.filter(n => /Price|Mileage|Year|Recommended|Newest|Lowest|Highest/i.test(n.name||"")).map(n=>`${n.ref}|${n.role}|${(n.name||'').slice(0,60)}`);
return { elemCount: o.total, menuish: menuish.slice(0,40) };

phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 10000 });
const cards = phi.query("[data-testid='vehicle-card']", { limit: 5, fields: ["data-testid", "href"] });
const o = phi.observe({ maxElements: 500 });
const links = o.nodes.filter(n => n.role === "link" && /\$/.test(n.name||"")).slice(0,10).map(n=>`${n.ref}|${(n.name||'').slice(0,140)}`);
const txt = phi.text();
const i = txt.indexOf("Lowest price");
return { cardsTotal: cards.total, cards: cards.items, links, textLen: txt.length, around: txt.slice(Math.max(0,i-200), i+900) };

const o = phi.observe({ maxElements: 400 });
const links = o.nodes.filter(n => n.role === "link" && /Honda Civic/i.test(n.name||"")).map(n=>`${n.ref}|${(n.name||'').slice(0,120)}`);
const btns = o.nodes.filter(n => /vehicle|card|detail|View/i.test(n.name||"")).slice(0,20).map(n=>`${n.ref}|${n.role}|${(n.name||'').slice(0,80)}`);
const anchors = phi.query("a[href*='/honda-civic/']", { limit: 10, fields: ["href"] });
return { links, btns, anchors };

const tabs = phi.tabs.list();
const anchors = phi.query("a[href*='/honda-civic/2']", { limit: 20, fields: ["href", "text"] });
return { tabs: tabs.map(t=>({tabId:t.tabId, url:t.url, active:t.active, drivable:t.drivable})), anchors };

const links = phi.query("a[href*='/honda-civic/2']", { limit: 40, fields: ["href"] , within: "main"});
const all = phi.query("a", { limit: 500, fields: ["href"] });
const veh = all.items.map(i=>i.href).filter(h=>/\/honda-civic\/\d{4}\/[a-z0-9]+/i.test(h||""));
const veh2 = all.items.map(i=>i.href).filter(h=>h && h.includes('/vehicle/'));
const sample = all.items.map(i=>i.href).filter(h=>h && /honda/i.test(h)).slice(0,30);
return { veh: Array.from(new Set(veh)).slice(0,20), veh2: Array.from(new Set(veh2)).slice(0,20), sample };

phi.keep("filters", { url: phi.tabs.list()[1].url.slice(0,120), results: [
 {year:2019, trim:"EX", miles:"22k", price:23990, id:4655505},
 {year:2023, trim:"EX", miles:"25k", price:24590, id:4721498}
]});
const g = phi.goto("https://www.carvana.com/vehicle/4655505");
phi.sleep(2500);
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 12000 });
const t = phi.text();
const feats = phi.query("li, div", { limit: 2000, fields: ["text"] });
const hit = feats.items.map(i=>i.text).filter(x=>x && /carplay|adaptive cruise|blind|blindspot|blind spot/i.test(x));
return { g: g.title, url: g.url, textLen: t.length, hits: Array.from(new Set(hit)).slice(0,30), head: t.slice(0,1200) };

const f = phi.recall("filters");
phi.narrate("回到筛选结果，核实一下总共有几辆符合条件的车");
phi.goto(f.url);
phi.sleep(2500);
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 15000 });
const t = phi.text();
const m = t.match(/(\d+)\s*(?:results|matches|vehicles|cars)/i);
const cards = phi.query("a[href*='/vehicle/']", { limit: 30, fields: ["href", "text"] });
const anchors = phi.query("a[href*='/vehicle/']", {limit: 30});
// broaden: read card containers
const all = phi.query("div, li", { limit: 3000, fields: ["text"] });
const priceLines = all.items.map(i => i.text).filter(x => x && /\$2[0-9],\d{3}/.test(x) && /miles/i.test(x) && x.length < 400);
return { matched: m ? m[0] : null, head: t.slice(0, 400), vehicleLinks: Array.from(new Set(cards.items.map(i=>i.href))).slice(0,20), priceLines: Array.from(new Set(priceLines)).slice(0,10) };

const url = phi.js(() => {
  const f = {filters:{cvnaFeatures:["Apple CarPlay","Adaptive Cruise Control","Blindspot Sensors"],price:{max:25000},mileage:{max:30000},makes:[{name:"Honda",parentModels:[{name:"Civic"}]}]},sortBy:"LowestPrice"};
  return "https://www.carvana.com/cars/filters?cvnaid=" + btoa(JSON.stringify(f));
});
phi.narrate("重新套用完整筛选条件，按价格从低到高看结果");
const g = phi.goto(url);
phi.sleep(3000);
phi.waitForNetworkIdle({ idleMs: 900, timeoutMs: 20000 });
const cards = phi.js(() => {
  const seen = new Set(); const out = [];
  for (const a of document.querySelectorAll("a[href*='/vehicle/']")) {
    const id = (a.getAttribute("href")||"").match(/\/vehicle\/(\d+)/);
    if (!id || seen.has(id[1])) continue;
    seen.add(id[1]);
    let el = a, txt = "";
    for (let i=0;i<6 && el;i++){ el = el.parentElement; if(el && el.innerText && el.innerText.length>60 && /miles/i.test(el.innerText)){ txt = el.innerText; break; } }
    out.push({id:id[1], href:a.getAttribute("href"), text:(txt||"").replace(/\s+/g," ").slice(0,240)});
    if (out.length>=8) break;
  }
  const body = document.body.innerText;
  const m = body.match(/Showing\s+([\d,]+)\s+results/i);
  return {count: m ? m[1] : null, cards: out};
});
return {url, title: g.title, cardsCount: cards.count, cards: cards.cards};
